use system.fs
use system.os
use system.collections.map

// The characters that make up a word.
let WORD_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

// Counts the words in `text`, folding ASCII letters to lower case.
fn count_words(text String) Map<String, int>
    var counts = Map<String, int>()
    var word = ""
    var i = 0
    let n = text.length()
    while i < n
        let ch = text.element_at(i)
        if WORD_CHARS.contains(ch)
            word = word + ch.to_lower()
        else if word.length() > 0
            add_word(counts, word)
            word = ""
        i += 1
    if word.length() > 0
        add_word(counts, word)
    return counts

fn add_word(counts Map<String, int>, word String)
    match counts.get(word)
        Some(c): counts.set(word, c + 1)
        None: counts.set(word, 1)

// Returns true when word `a` ranks before word `b`: higher count first,
// then the word itself in ascending byte order.
fn ranks_before(a String, a_count int, b String, b_count int) bool
    if a_count != b_count
        return a_count > b_count
    return a.compare(b) < 0

fn main()
    let args = Args()
    if args.length() == 0
        panic("usage: main <file>")
    let fs = Fs()
    match fs.read_file(args.element_at(0))
        Result.Ok(text): report(count_words(text))
        Result.Err(e): panic(f"cannot read {args.element_at(0)}")

// Prints up to ten words, most frequent first, by repeatedly taking the best
// remaining entry.
fn report(counts Map<String, int>)
    var remaining = counts
    var printed = 0
    while printed < 10 and remaining.length() > 0
        var best = ""
        var best_count = 0
        var i = 0
        while i < remaining.length()
            let w = remaining.element_at(i)
            let c = remaining.value_at(i)
            if i == 0 or ranks_before(w, c, best, best_count)
                best = w
                best_count = c
            i += 1
        println(f"{best} {best_count}")
        remaining.remove(best)
        printed += 1

