use system.fs
use system.os
use system.collections.list
use system.collections.map

// Reads the file named by the first argument and prints its ten most frequent
// words.
fn main()
    let args = Args()
    if args.length() == 0
        panic("usage: main <file>")
    let path = args.element_at(0)
    match Fs().read_file(path)
        Result.Ok(text): report(text)
        Result.Err(e): panic(f"cannot read {path}")

// Counts the words in `text`, folding ASCII letters to lower case. Every
// character outside A-Z, a-z and 0-9 separates words.
//
// The words are kept in two parallel lists, `words` and `counts`, and `slots`
// maps each word to its position in them. Walking the map by index would cost
// far more than walking a list, so the lists are the ones that get read back.
fn count_words(text String, slots Map<String, int>, words [String], counts [int])
    let word_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    var word = ""
    var i = 0
    let n = text.size()
    while i < n
        // One byte. A byte inside a multi-byte character is not a boundary, so
        // it reads as empty and separates words.
        let ch = text.substring(i, i + 1)
        if ch.length() == 1 and word_chars.contains(ch)
            word = word + ch.to_lower()
        else if word.length() > 0
            add_word(slots, words, counts, word)
            word = ""
        i += 1
    if word.length() > 0
        add_word(slots, words, counts, word)

fn add_word(slots Map<String, int>, words [String], counts [int], word String)
    match slots.get(word)
        Some(slot): counts.set(slot, counts.get(slot) + 1)
        None
            slots.set(word, words.length())
            words.push(word)
            counts.push(1)

// Returns true when entry `a` ranks before entry `b`: higher count first, then
// the word itself in ascending byte order.
fn ranks_before(a_word String, a_count int, b_word String, b_count int) bool
    if a_count != b_count
        return a_count > b_count
    return a_word.compare(b_word) < 0

// Prints up to ten entries, most frequent first. Each round takes the best entry
// that is left and removes it from the lists.
fn report(text String)
    let slots = Map<String, int>()
    let words = List<String>()
    let counts = List<int>()
    count_words(text, slots, words, counts)
    var printed = 0
    while printed < 10 and words.length() > 0
        var best = 0
        var i = 1
        while i < words.length()
            if ranks_before(words.get(i), counts.get(i), words.get(best), counts.get(best))
                best = i
            i += 1
        println(f"{words.get(best)} {counts.get(best)}")
        words.remove_at(best)
        counts.remove_at(best)
        printed += 1

